def check_good_triple(x, y, z):
    # Check if (x^z + 1) divides (x+1)^y
    numerator = (x + 1)**y
    denominator = x**z + 1
    if denominator == 0:
        return False # Should not happen since x >= 2, z >= 2
    return numerator % denominator == 0

