def get_prime_factors(n):
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

solutions = []
for x in range(2, 100):
    for z in range(2, 100):
        factors_xz1 = get_prime_factors(x**z + 1)
        factors_x1 = get_prime_factors(x + 1)
        if factors_xz1.issubset(factors_x1):
            solutions.append((x, z))

print(solutions)

import math

def is_power_of_3(n):
    if n <= 0:
        return False
    while n > 1:
        if n % 3 != 0:
            return False
        n //= 3
    return True

solutions = [] # Stores (z, k)

# We iterate z from 2 up to 99
for z in range(2, 100):
    value = 2**z + 1
    if is_power_of_3(value):
        # Find k such that 3^k = value
        k = round(math.log(value, 3))
        if 3**k == value:
            solutions.append((z, k))

print("Solutions (z, k) to 2^z + 1 = 3^k for 2 <= z <= 99:")
for z, k in solutions:
    print(f"z={z}, k={k} (2^{z} + 1 = 3^{k})")

total_count = 0
for z, k in solutions:
    # If 2^z + 1 = 3^k, then we require 3^k | 3^y, which means k <= y.
    # Since 1 <= y <= 99, the valid values for y are {k, k+1, ..., 99}.
    # The count is 99 - k + 1 = 100 - k.
    count_for_z = 100 - k
    total_count += count_for_z

print(f"\nTotal count for x=2, z>1: {total_count}")

def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1)) == 0

